import { ReactElement, ReactFragment, ReactNode, ReactPortal } from 'react';
import {
  Accessor as _InternalAccessor,
  Column as _InternalColumn,
} from 'react-table';

import type {
  ColumnGroup,
  SingleColumn,
  TableColumn,
  TableColumnAccessor,
} from './shared-table-types.js';
import { DATA_TABLE_DEFAULT_COLUMN_WIDTH } from '../DataTable/constants.js';

/**
 * Maps API columns to internal columns (react-table compatible).
 * @internal
 */
export function _convertColumns(
  columns: TableColumn[],
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
): _InternalColumn<any>[] {
  return columns.map(_convertColumn);
}

function _isColumnGroup(column: TableColumn): column is ColumnGroup {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  if ((column as any)['columns']) {
    return true;
  }
  return false;
}

/**
 * Maps API column to internal column (react-table compatible).
 * @internal
 */
export function _convertColumn(
  column: TableColumn,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
): _InternalColumn<any> {
  const result = convertColumnCommon(column);

  if (_isColumnGroup(column)) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (result as any)['columns'] = _convertColumns(column['columns']);
  }

  const originalAccessor = column['accessor'];
  if (originalAccessor) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (result as any)['accessor'] = convertAccessor(originalAccessor);
    if (
      typeof originalAccessor === 'string' &&
      isAccessorStringEscaped(originalAccessor) &&
      column['id'] === undefined
    ) {
      result['id'] = getAccessorUnescaped(originalAccessor);
    }
  }

  if (column.width === undefined && column.autoWidth !== true) {
    result.width = DATA_TABLE_DEFAULT_COLUMN_WIDTH;
  }

  // set the default value for the column alignment
  if (column.alignment === undefined && column.columnType === undefined) {
    result.alignment = 'left';
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return filterUndefinedValues(result as _InternalColumn<any>);
}

/**
 * Maps parts common to all table columns (data, simple).
 * @internal
 */
function convertColumnCommon(originalColumn: TableColumn) {
  const { header, cell, ...rest } = originalColumn;
  const headerOrFallback = getHeaderOrFallback(header, originalColumn);
  const result = {
    Header: headerOrFallback,
    Cell: cell,
    ...rest,
  };
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  delete (result as any)['header'];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  delete (result as any)['cell'];
  return result;
}

/**
 * If header is defined then return that. Otherwise if accessor is a string,
 * use that as a fallback. If accessor is a function then use the id string
 * as a fallback. Otherwise it's a column with no header (e.g. expandable).
 * @param header - original header
 * @param column - column information
 *
 * @returns header or header fallback if possible.
 */
function getHeaderOrFallback(
  header:
    | string
    | ReactElement
    | ReactFragment
    | ReactPortal
    | ((props: unknown) => ReactNode)
    | undefined,
  column: TableColumn,
):
  | string
  | ReactElement
  | ReactFragment
  | ReactPortal
  | ((props: unknown) => ReactNode)
  | null {
  if (header) {
    return header;
  }

  const { accessor } = column as SingleColumn;

  if (typeof accessor === 'string') {
    return isAccessorStringEscaped(accessor)
      ? getAccessorUnescaped(accessor)
      : accessor;
  }
  if (typeof accessor === 'function' && column.id) {
    return column.id;
  }

  // in this case, there is no fallback
  // e.g. expandable column (should not have header)
  return null;
}

/**
 * Filters out entries with undefined and null values.
 * @param col - unfiltered object
 *
 * @returns filtered object
 * @internal
 */
function filterUndefinedValues(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  col: _InternalColumn<any>,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
): _InternalColumn<any> {
  return Object.fromEntries(
    Object.entries(col).filter(([, v]) => v !== undefined && v !== null),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  ) as _InternalColumn<any>;
}

/**
 * Maps API accessor to internal accessor (react-table compatible).
 * @param originalAccessor - our API type
 *
 * @returns react-table type
 * @internal
 */
function convertAccessor(
  originalAccessor?: string | TableColumnAccessor<never>,
): string | _InternalAccessor<never> {
  if (typeof originalAccessor === 'string') {
    if (isAccessorStringEscaped(originalAccessor)) {
      return (data) => data[getAccessorUnescaped(originalAccessor)];
    }
    return originalAccessor;
  }
  return originalAccessor as _InternalAccessor<never>;
}

/**
 * Checks if string starts and ends with double or single quotes.
 * @param accessorString - string to check
 *
 * @returns true if start and end characters are matching double or single quotes.
 * @internal
 */
export function isAccessorStringEscaped(accessorString: string): boolean {
  return (
    (accessorString.startsWith('"') && accessorString.endsWith('"')) ||
    (accessorString.startsWith("'") && accessorString.endsWith("'"))
  );
}

/**
 * Precondition: {@link isAccessorStringEscaped} is true for the given parameter.
 * @param escapedAccessorString - accessor string with quotes at start and end.
 *
 * @returns unescaped string
 * @internal
 */
export function getAccessorUnescaped(escapedAccessorString: string): string {
  return escapedAccessorString.substring(1, escapedAccessorString.length - 1);
}
